  props: {
    variant: {
      type: String,
      validator (value) {
        return [
          'default', // Display the contribution
          'unfilled', // Add a new contribution
          'editable' // Edit a contribution
        ].indexOf(value) > -1
      },
      default: 'default'
    },
    initialValue: {
      type: String
    },
    needsIncome: Boolean,
    contributionsList: Array
